options.customCss:
:root {
	/* Typography */
	--font-family-header: 'Playfair Display', serif;
	--font-family-body: 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 14px;
	--font-size-label: 15px;
	--font-size-input: 15px;
	--font-size-header: 24px;
	--font-size-paragraph: 14px;
	--font-size-link: 13px;
	--font-size-error: 13px;
	--font-size-html-h1: 32px;
	--font-size-html-h2: 24px;
	--font-size-html-h3: 18px;
	--font-size-html-h4: 16px;
	--font-size-html-h5: 14px;
	--font-size-html-h6: 12px;
	--font-size-subheader: 16px;

	/* Colors (Tahayyül Identity) */
	--color-background: #fdfcf9;         /* Warm off-white */
	--color-card-bg: #ffffff;
	--color-card-border: #e0e0e0;
	--color-card-shadow: rgba(20, 20, 20, 0.06);

	--color-header: #1c2d40;             /* Deep Ottoman blue */
	--color-header-subtext: #7d8a96;
	--color-label: #444444;
	--color-input-text: #333333;
	--color-input-border: #d9d9d9;
	--color-focus-border: #c49a6c;       /* Gold accent */

	--color-link: #006d6f;               /* Teal/Emerald for links */
	--color-html-link: #c49a6c;          /* Golden link accent */
	--color-html-text: #4a4a4a;

	--color-submit-btn-bg: #1c2d40;      /* Premium dark blue */
	--color-submit-btn-text: #ffffff;
	--color-clear-button-bg: #7d8a96;

	--color-required: #c49a6c;
	--color-error: #d9534f;
	--color-test-notice-text: #c49a6c;
	--color-test-notice-bg: #fdf8f3;
	--color-test-notice-border: #f1e0c9;

	/* Border Radii */
	--border-radius-card: 10px;
	--border-radius-input: 8px;
	--border-radius-clear-btn: 50%;

	/* Spacing */
	--padding-container-top: 28px;
	--padding-card: 28px;
	--margin-bottom-card: 18px;
	--padding-form-input: 14px;

	/* Dimensions */
	--container-width: 480px;
	--submit-btn-height: 50px;
	--checkbox-size: 18px;

	/* Effects */
	--box-shadow-card: 0px 6px 18px rgba(0,0,0,0.06);
	--opacity-placeholder: 0.6;
}

/* Logo Section */
.brand-logo {
	width: 100%;
	display: flex;
	justify-content: center; /* Center horizontally */
	margin-top: 16px;
	margin-bottom: 20px;
}

.brand-logo img {
	max-height: 50px;   /* Small elegant size */
	width: auto;
	object-fit: contain;
	opacity: 0.95;      /* Slight refinement for luxury feel */
}

